fn channels(base: u32) -> &'static [u32] {
    match base {
        0xa06f => &[0xa06f],
        0xa16f => &[0xa16f],
        0xb06f => &[0xb06f],
        0xc06f => &[0xc06f],
        0xc36f => &[0xc36f],
        0xc46f => &[0xc46f, 0xc56f, 0xc86f, 0xc96f, 0xca6f],
        _ => unreachable!(),
    }
}
#[test]
fn public_header_semaphore_goldens() {
    for &(base, wide, address, value, acquire, timestamp, expected) in SEM_GOLDENS {
        for &class in channels(base) {
            let mut words = vec![0xfeedface];
            host_semaphore(&mut words, class, wide, address, value, acquire, timestamp).unwrap();
            assert_eq!(words[0], 0xfeedface);
            assert_eq!(&words[1..],expected,"class={class:x} wide={wide} address={address:x} value={value:x} acquire={acquire} timestamp={timestamp}");
        }
    }
}
#[test]
fn public_header_visibility_goldens() {
    for &(base, expected) in VIS_GOLDENS {
        for &class in channels(base) {
            let mut words = Vec::new();
            host_visibility(&mut words, class).unwrap();
            assert_eq!(words, expected, "class={class:x}");
        }
    }
}
#[test]
fn invalid_host_contracts_leave_packets_unchanged() {
    for class in [
        0xa06f, 0xa16f, 0xb06f, 0xc06f, 0xc36f, 0xc46f, 0xc56f, 0xc86f, 0xc96f, 0xca6f,
    ] {
        for address in [1, 8, 15, 0xffffffffff, 1 << 40, u64::MAX] {
            let mut words = vec![0xfeedface];
            assert!(host_semaphore(&mut words, class, false, address, 0, false, false).is_err());
            assert_eq!(words, [0xfeedface]);
        }
    }
    for class in [0xa06f, 0xa16f, 0xb06f, 0xc06f] {
        let mut words = vec![0xfeedface];
        assert!(host_semaphore(&mut words, class, true, 0, 0, false, false).is_err());
        assert_eq!(words, [0xfeedface]);
    }
    for class in [0, 0x906f, 0xffff] {
        let mut words = vec![0xfeedface];
        assert!(host_semaphore(&mut words, class, false, 0, 0, false, false).is_err());
        assert!(host_visibility(&mut words, class).is_err());
        assert_eq!(words, [0xfeedface]);
    }
}

// Constants emitted by build/gpu-coverage/typed-va-oracle.c (public615 headers).
const C_VIRTUAL_ALLOC: u32 = 0x80100;
const C_FIXED_ALLOC: u32 = 0x10;
const C_PAGE_ATTR: u32 = 0x800000;
const C_NO_ZBC: u32 = 0x1;
const C_VIRTUAL_CLASS: u32 = 0x50a0;
const C_BASE_MAP: u32 = 0x110;
const C_VIRTUAL_MAP: u32 = 0x8;
const C_FIXED_MAP: u32 = 0x8000;
const C_KIND_OVERRIDE: u32 = 0x80000;

#[test]
fn public_header_typed_va_and_direct_kind_contracts() {
    for (version, typed_kind) in [
        ("390.116", true),
        ("545.29.06", true),
        ("550.54.14", true),
        ("580.65.06", false),
        ("615.71.09", false),
    ] {
        let compat = crate::compat::Compat::for_version(version).unwrap();
        for kind in [None, Some(0), Some(1), Some(0x7b), Some(255)] {
            for address in [None, Some(0), Some(0x12345000), Some((1u64 << 40) - 8192)] {
                let plan = super::mapping_plan(compat, 4096, 8192, 16384, address, kind).unwrap();
                let fixed = address.is_some();
                let typed = typed_kind && kind.is_some();
                assert_eq!(
                    plan.flags,
                    C_BASE_MAP
                        | if fixed { C_FIXED_MAP } else { 0 }
                        | if typed {
                            C_VIRTUAL_MAP
                        } else if kind.is_some() {
                            C_KIND_OVERRIDE
                        } else {
                            0
                        },
                    "{version}"
                );
                assert_eq!(plan.wire_kind, if typed { 0 } else { kind.unwrap_or(0) });
                assert_eq!(plan.typed.is_some(), typed);
                if let Some(params) = plan.typed {
                    assert_eq!(
                        params.flags,
                        C_VIRTUAL_ALLOC | if fixed { C_FIXED_ALLOC } else { 0 }
                    );
                    assert_eq!(params.attr, C_PAGE_ATTR);
                    assert_eq!(params.attr2, C_NO_ZBC);
                    assert_eq!(params.format, kind.unwrap());
                    assert_eq!(params.size, 8192);
                    assert_eq!(params.alignment, 4096);
                    assert_eq!(params.offset, address.unwrap_or(0));
                    assert_eq!(params.limit, 8191);
                }
            }
        }
    }
    assert_eq!(super::TYPED_VA_CLASS, C_VIRTUAL_CLASS);
}
